const __pageData = JSON.parse('{"title":"2022赛季视觉部第二次培训——相机成像原理与相机标定","description":"","frontmatter":{"layout":"post","title":"2022赛季视觉部第二次培训——相机成像原理与相机标定","categories":["vision","course","camera"],"source_type":"repost","source_project":"SJTU RoboMaster Team Blog","source_url":"https://github.com/SJTU-RoboMaster-Team/SJTU-RoboMaster-Team.github.io/blob/master/_posts/2021-10-10-vision-learning-2.md","license":"MIT"},"headers":[],"relativePath":"blog/imported/sjtu/2021-10-10-vision-learning-2.md","filePath":"blog/imported/sjtu/2021-10-10-vision-learning-2.md","lastUpdated":null}');
